fn fibonacci_uses_the_original_two_step_recursive_domain() {
    let code = "have fn fib(n Z: n >= 0) R by induc n from 0:
    case n < 2: 1
    case n >= 2: fib(n - 2) + fib(n - 1)
fib(0) = 1
fib(1) = 1
fib(2) = fib(2 - 2) + fib(2 - 1)
fib(2 - 2) = fib(0)
fib(2 - 1) = fib(1)
fib(2) = fib(0) + fib(1) = 2
";
    let run = runtime().run_litex_code(code).unwrap();
    assert!(run.session_error.is_none(), "{:?}", run.session_error);
    assert!(run.success);
}

