fn full_add2_chain_and_projection_boundaries() {
    let detailed = check(
        include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/examples/proof_nodes/equal/by_builtin_strategy/add2_calculation_chain.lit"
        )),
        true,
    );
    for node in [
        "TupleComponentEquality",
        "ArithmeticCongruence",
        "LiteralTupleProjectionMembership",
        "TupleComponentAtIndex",
    ] {
        assert!(detailed.contains(node), "{node}");
    }
    let definition = "have fn add2(u,v cart(R,R)) cart(R,R)=(u[1]+v[1],u[2]+v[2])\n";
    check(
        &format!("{definition}add2((1,2),(3,4))=(1+3,2+4)=(4,7)"),
        false,
    );
    check(&format!("{definition}add2((1,2,3),(3,4))=(4,6)"), false);
    for code in [
        "(1,-2)[2] $in N",
        "(1,2)[0]=1",
        "(1,2)[3]=1",
        "(1/0+1,2)=(1/0+1,2)",
        "1+2=1*2",
    ] {
        check(code, false);
    }
}

fn finite_set_cardinality_rule_detailed_retains_winning_route_and_premises() {
    for (code, rule, expected_keys, route) in [
        (
            EQUAL_SIZE,
            "FiniteSetEqualFromSubsetSize",
            vec!["size_equal_proof", "subset_proof"],
            None,
        ),
        (
            WEAK_SIZE,
            "FiniteSetSizeSubsetLe",
            vec!["subset_proof"],
            None,
        ),
        (
            STRICT_SIZE,
            "FiniteSetSizeProperSubsetLt",
            vec!["subset_proof", "not_equal_proof"],
            Some("BySubsetAndNotEqual"),
        ),
        (
            NAMED_STRICT_SIZE,
            "FiniteSetSizeProperSubsetLt",
            vec!["proper_subset_proof"],
            Some("ByProperSubset"),
        ),
    ] {
        let mut rt = runtime(OutputLanguage::English);
        let result = exec(&mut rt, code);
        assert!(!result.is_failed(), "{code}");
        let detailed = project_stmt_detailed(&result, &rt);
        let node = find_field(&detailed, "rule", rule).expect("winning rule");
        for key in expected_keys {
            assert!(contains_key(node, key), "{rule}: {key}");
        }
        assert!(
            contains_key(node, "cite_fact_id"),
            "must cite checked source premises"
        );
        if let Some(route) = route {
            assert!(find_field(node, "route", route).is_some());
        }
        // Cardinality WD retains finite-set evidence even when A was just `set`.
        assert!(contains_key(&detailed, "well_defined"));
    }
    let mut rt = runtime(OutputLanguage::English);
    let result = exec(
        &mut rt,
        "have A set = intersect({1}, R)\nA $subset {1}\n$is_finite_set(A)",
    );
    assert!(!result.is_failed());
    let detailed = project_stmt_detailed(&result, &rt);
    let node = find_field(&detailed, "strategy", "SubsetOfFiniteSet").expect("subset strategy");
    assert!(contains_key(node, "proof_of_requirement_facts"));
    assert!(contains_key(node, "cite_fact_id"));
}

fn finite_set_cardinality_rule_normal_explains_actual_certificates_in_both_languages() {
    for (language, equal_label, strict_label) in [
        (
            OutputLanguage::English,
            "Equal finite subset cardinality",
            "Proper finite subset cardinality",
        ),
        (
            OutputLanguage::Chinese,
            "有限子集等大则相等",
            "有限真子集的基数严格更小",
        ),
    ] {
        for (code, label) in [
            (EQUAL_SIZE, equal_label),
            (STRICT_SIZE, strict_label),
            (NAMED_STRICT_SIZE, strict_label),
        ] {
            let mut rt = runtime(language);
            let result = exec(&mut rt, code);
            assert!(!result.is_failed());
            let conclusion = last_conclusion(result);
            let normal = project_stmt_normal(&conclusion, &rt);
            let text = stringify_normal(&normal);
            // Chinese Normal localizes field names as well as the explanation.
            assert!(text.contains(label), "{label}: {text}");
        }
    }
}

fn induction_goal_wd_uses_the_induction_domain_without_ih() {
    for keyword in ["induc", "strong_induc"] {
        check(
            &format!("have fn f(x N) N = x\nby {keyword} n from 0:\n    ? f(n) = f(n)\n"),
            &[true, true],
        );
        check(
            &format!("have fn f(x N) N = x\nby {keyword} n from -1:\n    ? f(n) = f(n)\n"),
            &[true, false],
        );
        check(
            &format!("by {keyword} n from 0:\n    ? n / n = n / n\n"),
            &[false],
        );
        check(
            &format!("by {keyword} n from 0.5:\n    ? n = n\n"),
            &[false],
        );
    }
}

fn builtin_permission_and_depth_are_inherited() {
    use crate::ast::stmt::Stmt;
    use crate::execute::execute_fact_stmt::VerifyState;
    use crate::tokenize::Tokenizer;
    for (setup, goal) in [
        ("have A,B finite_set\nfinite_set_size(cart(A,B)) = finite_set_size(cart(A,B))\nfinite_set_size(A)*finite_set_size(B) = finite_set_size(A)*finite_set_size(B)", "finite_set_size(cart(A,B)) = finite_set_size(A)*finite_set_size(B)"),
        ("have z,w C\nC_abs(z*w) = C_abs(z*w)\nC_abs(z)*C_abs(w) = C_abs(z)*C_abs(w)", "C_abs(z*w) = C_abs(z)*C_abs(w)"),
        ("have x,y R\nsin(x-y) = sin(x-y)\nsin(x)*cos(y)-cos(x)*sin(y) = sin(x)*cos(y)-cos(x)*sin(y)", "sin(x-y) = sin(x)*cos(y)-cos(x)*sin(y)"),
        ("have op fn(a,b R)R\nhave f fn(k Z)R\nreduce(1,4,f,op,0) = reduce(1,4,f,op,0)\nreduce(3,4,f,op,reduce(1,2,f,op,0)) = reduce(3,4,f,op,reduce(1,2,f,op,0))", "reduce(1,4,f,op,0) = reduce(3,4,f,op,reduce(1,2,f,op,0))"),
        ("have f fn(x union({1,2},{3}))R\nnot 3 $in {1,2}\nfinite_set_product(union({1,2},{3}),f) = finite_set_product(union({1,2},{3}),f)\nfinite_set_product({1,2},fn(x {1,2})R {f(x)})*f(3) = finite_set_product({1,2},fn(x {1,2})R {f(x)})*f(3)", "finite_set_product(union({1,2},{3}),f) = finite_set_product({1,2},fn(x {1,2})R {f(x)})*f(3)"),
    ] {
        let mut rt = Runtime::new(LaunchCommand::Eval { code: String::new(), session: false, strict: true, language: OutputLanguage::English });
        assert!(rt.run_litex_code(setup).unwrap().success, "{setup}");
        let tokens = Tokenizer::new().tokenize(goal, rt.current_file.clone()).unwrap();
        let statements = rt.parse(&tokens).unwrap();
        let Stmt::Fact(fact) = &statements[0] else { panic!("fact expected"); };
        let before = rt.execution_environments_stack.iter().map(|e| (e.facts.facts_by_id.len(), e.well_defined_objects.object_to_wd_id.len())).collect::<Vec<_>>();
        let mut state = VerifyState::top_level();
        state = VerifyState::new(crate::execute::execute_fact_stmt::VerifyStateLevel::KnownSpecialProperty);
        assert!(rt.verify_fact(fact, state.clone()).unwrap().is_failed(), "disabled entry: {goal}");
        state = VerifyState::new(crate::execute::execute_fact_stmt::VerifyStateLevel::BuiltinRule);
        assert!(!rt.verify_fact(fact, state).unwrap().is_failed(), "zero deep depth: {goal}");
        let after = rt.execution_environments_stack.iter().map(|e| (e.facts.facts_by_id.len(), e.well_defined_objects.object_to_wd_id.len())).collect::<Vec<_>>();
        assert_eq!(before, after, "search must not publish evidence: {goal}");
    }
}

