fn normal_bilingual_contract() {
    for (source, en, zh) in [
        ("have A,B finite_set\nfinite_set_size(cart(A,B)) = finite_set_size(A)*finite_set_size(B)", "Finite Cartesian cardinality", "有限笛卡尔积的基数"),
        ("have z,w C\nC_abs(z*w) = C_abs(z)*C_abs(w)", "Multiplicativity of complex modulus", "复数模的乘法公式"),
        ("have x,y R\nsin(x-y) = sin(x)*cos(y)-cos(x)*sin(y)", "Sine difference formula", "正弦差角公式"),
        ("have x,y R\ncos(x-y) = cos(x)*cos(y)+sin(x)*sin(y)", "Cosine difference formula", "余弦差角公式"),
        ("have op fn(a,b R)R\nhave f fn(k Z)R\nreduce(1,4,f,op,0) = reduce(3,4,f,op,reduce(1,2,f,op,0))", "Adjacent left-fold partition", "左折叠的相邻分段"),
        ("have f fn(x union({1,2},{3}))R\nnot 3 $in {1,2}\nfinite_set_product(union({1,2},{3}),f) = finite_set_product({1,2},fn(x {1,2})R {f(x)})*f(3)", "Fresh insertion into a finite product", "有限乘积插入新元素"),
    ] {
      for (language, expected_text) in [(OutputLanguage::English, en), (OutputLanguage::Chinese, zh)] {
        let mut rt = Runtime::new(LaunchCommand::Eval {
            code: String::new(),
            session: false,
            strict: true,
            language,
        });
        let result = rt.run_litex_code(source).unwrap();
        assert!(result.success);
        assert!(emit_run_normal(&result, &rt, "eval", None).contains(expected_text));
      }
    }
}

fn induction_examples_cover_the_maintained_acceptance_sources() {
    for path in [
        "examples/stmt_nodes/definition/inductive_nested_cases.lit",
        "examples/stmt_nodes/definition/template_inductive_arithmetic.lit",
        "examples/stmt_nodes/by/induction_domain_and_proof_actions.lit",
        "examples/stmt_nodes/by/induction_collection_binders.lit",
    ] {
        let source =
            std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(path))
                .unwrap();
        let mut rt = Runtime::new(LaunchCommand::Eval {
            code: String::new(),
            session: false,
            strict: true,
            language: OutputLanguage::English,
        });
        let run = rt.run_litex_code(&source).unwrap();
        assert!(
            run.success && run.session_error.is_none(),
            "{path}: {:?}",
            run.session_error
        );
        assert!(
            run.statement_results.iter().all(|s| !s.is_failed()),
            "{path}"
        );
    }
}

